// Writes an integer with digit grouping.
template <typename OutputIt, typename UInt, typename Char>
auto write_int(OutputIt out, UInt value, unsigned prefix,
               const format_specs<Char>& specs,
               const digit_grouping<Char>& grouping) -> OutputIt {
  static_assert(std::is_same<uint64_or_128_t<UInt>, UInt>::value, "");

  int base_bits = 0;
  bool upper = false;
  switch (specs.type) {
  case presentation_type::none:
  case presentation_type::dec:
    break;
  case presentation_type::hex_lower:
  case presentation_type::hex_upper:
    base_bits = 4;
    upper = specs.type == presentation_type::hex_upper;
    break;
  case presentation_type::bin_lower:
  case presentation_type::bin_upper:
    base_bits = 1;
    upper = specs.type == presentation_type::bin_upper;
    break;
  case presentation_type::oct:
    base_bits = 3;
    break;
  case presentation_type::chr:
    return write_char(out, static_cast<Char>(value), specs);
  default:
    throw_format_error("invalid format specifier");
  }

  // The buffer should be large enough to hold all digits of a 128-bit integer
  // in binary.
  char digits[128];
  int num_digits = 0;
  switch (base_bits) {
  case 1:
    num_digits = count_digits<1>(value);
    format_uint<1>(digits, value, num_digits, upper);
    break;
  case 3:
    num_digits = count_digits<3>(value);
    format_uint<3>(digits, value, num_digits, upper);
    break;
  case 4:
    num_digits = count_digits<4>(value);
    format_uint<4>(digits, value, num_digits, upper);
    break;
  default: {
    num_digits = 1;
    UInt counted = value;
    for (;;) {
      if (counted < 10) break;
      if (counted < 100) {
        num_digits += 1;
        break;
      }
      if (counted < 1000) {
        num_digits += 2;
        break;
      }
      if (counted < 10000) {
        num_digits += 3;
        break;
      }
      counted /= 10000u;
      num_digits += 4;
    }
    char* digit_out = digits + num_digits;
    UInt remaining = value;
    while (remaining >= 100) {
      digit_out -= 2;
      unsigned remainder = static_cast<unsigned>(remaining % 100);
      const char* pair = digits2(static_cast<size_t>(remainder));
      digit_out[0] = pair[0];
      digit_out[1] = pair[1];
      remaining /= 100;
    }
    if (remaining < 10) {
      *--digit_out = static_cast<char>('0' + remaining);
    } else {
      digit_out -= 2;
      const char* pair = digits2(static_cast<size_t>(remaining));
      digit_out[0] = pair[0];
      digit_out[1] = pair[1];
    }
    break;
  }
  }

  switch (specs.type) {
  case presentation_type::hex_lower:
  case presentation_type::hex_upper:
    if (specs.alt)
      prefix_append(prefix, unsigned(upper ? 'X' : 'x') << 8 | '0');
    break;
  case presentation_type::bin_lower:
  case presentation_type::bin_upper:
    if (specs.alt)
      prefix_append(prefix, unsigned(upper ? 'B' : 'b') << 8 | '0');
    break;
  case presentation_type::oct:
    // Octal prefix '0' is counted as a digit, so only add it if precision
    // is not greater than the number of digits.
    if (specs.alt && specs.precision <= num_digits && value != 0)
      prefix_append(prefix, '0');
    break;
  default:
    break;
  }

  string_view digit_view(digits, to_unsigned(num_digits));
  int separator_count = grouping.count_separators(num_digits);
  unsigned prefix_size = prefix >> 24;
  unsigned grouped_size =
      prefix_size + to_unsigned(num_digits) + to_unsigned(separator_count);
  unsigned spec_width = to_unsigned(specs.width);
  size_t padding = spec_width > grouped_size ? spec_width - grouped_size : 0;
  const char* shifts = "\x00\x1f\x00\x01";
  unsigned align_index = static_cast<unsigned>(specs.align);
  size_t left_padding = padding >> shifts[align_index];
  size_t right_padding = padding - left_padding;
  size_t fill_size = specs.fill.size();
  const Char* fill_data = specs.fill.data();
  auto it = reserve(out, grouped_size + padding * fill_size);
  if (left_padding != 0) {
    for (size_t n = 0; n < left_padding; ++n) {
      const Char* fill_begin = fill_data;
      const Char* fill_end = fill_data + fill_size;
      while (fill_begin != fill_end) {
        *it++ = static_cast<Char>(*fill_begin++);
      }
    }
  }
  if (prefix != 0) {
    for (unsigned p = prefix & 0xffffff; p != 0; p >>= 8)
      *it++ = static_cast<Char>(p & 0xff);
  }
  if (!grouping.has_separator()) {
    it = copy_str<Char>(digit_view.begin(), digit_view.end(), it);
  } else {
    it = grouping.apply(it, digit_view);
  }
  if (right_padding != 0) {
    for (size_t n = 0; n < right_padding; ++n) {
      const Char* fill_begin = fill_data;
      const Char* fill_end = fill_data + fill_size;
      while (fill_begin != fill_end) {
        *it++ = static_cast<Char>(*fill_begin++);
      }
    }
  }
  return base_iterator(out, it);
}

